```tsx
// src/components/CheckoutScreen.tsx

import React, { useMemo, useState } from "react";
import type { AddressErrors, CartItem, DeliveryAddress } from "../types/checkout";
import "./CheckoutScreen.css";

interface CheckoutScreenProps {
  cartItems: CartItem[];
  currency?: string;
  isSubmitting?: boolean;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => void;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  city: "",
  street: "",
  apartment: "",
  postalCode: "",
  comment: "",
};

const PHONE_REGEX = /^[+]?[\d\s()-]{7,20}$/;

function formatPrice(value: number, currency: string): string {
  return `${value.toFixed(2)} ${currency}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = "Full name is required";
  }

  if (!address.phone.trim()) {
    errors.phone = "Phone number is required";
  } else if (!PHONE_REGEX.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }

  if (!address.city.trim()) {
    errors.city = "City is required";
  }

  if (!address.street.trim()) {
    errors.street = "Street address is required";
  }

  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required";
  }

  return errors;
}

export default function CheckoutScreen({
  cartItems,
  currency = "USD",
  isSubmitting = false,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Record<string, boolean>>({});

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );

  const deliveryFee = subtotal > 0 ? 4.99 : 0;
  const total = subtotal + deliveryFee;

  const handleFieldChange = (field: keyof DeliveryAddress, value: string) => {
    setAddress((prev) => ({ ...prev, [field]: value }));
  };

  const handleFieldBlur = (field: keyof DeliveryAddress) => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress({ ...address }));
  };

  const handlePay = () => {
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      postalCode: true,
    });

    if (Object.keys(validationErrors).length === 0 && cartItems.length > 0) {
      onPay(address);
    }
  };

  const isPayDisabled = isSubmitting || cartItems.length === 0;

  return (
    <div className="checkout-screen">
      <header className="checkout-header">
        <button
          type="button"
          className="back-button"
          onClick={onBack}
          aria-label="Back to cart"
        >
          <span className="back-arrow" aria-hidden="true">
            &#8592;
          </span>
          Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </header>

      <main className="checkout-content">
        <section className="checkout-section" aria-labelledby="cart-items-heading">
          <h2 id="cart-items-heading" className="section-title">
            Your items
          </h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    className="cart-item-image"
                    src={item.imageUrl}
                    alt={item.title}
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-title">{item.title}</span>
                    <span className="cart-item-quantity">
                      Qty: {item.quantity}
                    </span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity, currency)}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>

        <section className="checkout-section" aria-labelledby="address-heading">
          <h2 id="address-heading" className="section-title">
            Delivery address
          </h2>

          <form
            className="address-form"
            onSubmit={(e) => {
              e.preventDefault();
              handlePay();
            }}
          >
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange("fullName", e.target.value)}
                onBlur={() => handleFieldBlur("fullName")}
                placeholder="Jane Doe"
                autoComplete="name"
              />
              {touched.fullName && errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={(e) => handleFieldChange("phone", e.target.value)}
                onBlur={() => handleFieldBlur("phone")}
                placeholder="+1 555 123 4567"
                autoComplete="tel"
              />
              {touched.phone && errors.phone && (
                <span className="field-error">{errors.phone}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="city">City</label>
              <input
                id="city"
                type="text"
                value={address.city}
                onChange={(e) => handleFieldChange("city", e.target.value)}
                onBlur={() => handleFieldBlur("city")}
                placeholder="New York"
                autoComplete="address-level2"
              />
              {touched.city && errors.city && (
                <span className="field-error">{errors.city}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field form-field-grow">
                <label htmlFor="street">Street address</label>
                <input
                  id="street"
                  type="text"
                  value={address.street}
                  onChange={(e) => handleFieldChange("street", e.target.value)}
                  onBlur={() => handleFieldBlur("street")}
                  placeholder="123 Main St"
                  autoComplete="address-line1"
                />
                {touched.street && errors.street && (
                  <span className="field-error">{errors.street}</span>
                )}
              </div>

              <div className="form-field form-field-small">
                <label htmlFor="apartment">Apt / Suite</label>
                <input
                  id="apartment"
                  type="text"
                  value={address.apartment}
                  onChange={(e) =>
                    handleFieldChange("apartment", e.target.value)
                  }
                  placeholder="Optional"
                  autoComplete="address-line2"
                />
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="postalCode">Postal code</label>
              <input
                id="postalCode"
                type="text"
                value={address.postalCode}
                onChange={(e) =>
                  handleFieldChange("postalCode", e.target.value)
                }
                onBlur={() => handleFieldBlur("postalCode")}
                placeholder="10001"
                autoComplete="postal-code"
              />
              {touched.postalCode && errors.postalCode && (
                <span className="field-error">{errors.postalCode}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="comment">Delivery notes (optional)</label>
              <textarea
                id="comment"
                value={address.comment}
                onChange={(e) => handleFieldChange("comment", e.target.value)}
                placeholder="Leave at the front desk, ring the bell, etc."
                rows={3}
              />
            </div>
          </form>
        </section>

        <section className="checkout-section" aria-labelledby="summary-heading">
          <h2 id="summary-heading" className="section-title">
            Order summary
          </h2>
          <div className="summary-row">
            <span>Subtotal</span>
            <span>{formatPrice(subtotal, currency)}</span>
          </div>
          <div className="summary-row">
            <span>Delivery</span>
            <span>{formatPrice(deliveryFee, currency)}</span>
          </div>
          <div className="summary-row summary-total">
            <span>Total</span>
            <span>{formatPrice(total, currency)}</span>
          </div>
        </section>
      </main>

      <footer className="checkout-footer">
        <button
          type="button"
          className="pay-button"
          disabled={isPayDisabled}
          onClick={handlePay}
        >
          {isSubmitting ? "Processing…" : `Pay ${formatPrice(total, currency)}`}
        </button>
      </footer>
    </div>
  );
}
```

